import{_ as o,r as t,o as p,c as r,e as a,a as i,s as l}from"./chunks/framework.CXcwiNg-.js";const y=JSON.parse('{"title":"Seeding Themes - October CMS - 3.x","titleTemplate":false,"description":"Populate blueprints and database records with sample content.","frontmatter":{"subtitle":"Populate blueprints and database records with sample content."},"headers":[{"level":2,"title":"Directory Structure","slug":"directory-structure","link":"#directory-structure","children":[]},{"level":2,"title":"Importing Blueprints","slug":"importing-blueprints","link":"#importing-blueprints","children":[]},{"level":2,"title":"Importing Languages","slug":"importing-languages","link":"#importing-languages","children":[]},{"level":2,"title":"Importing Data","slug":"importing-data","link":"#importing-data","children":[{"level":3,"title":"Example Data File","slug":"example-data-file","link":"#example-data-file","children":[]}]},{"level":2,"title":"Seeding a Theme","slug":"seeding-a-theme","link":"#seeding-a-theme","children":[]}],"relativePath":"3.x/cms/themes/seeding-themes.md","filePath":"3.x/cms/themes/seeding-themes.md"}'),c={name:"3.x/cms/themes/seeding-themes.md"};function d(u,e,g,h,m,k){const n=t("pre-heading"),s=t("post-heading");return p(),r("div",null,[a(n),e[0]||(e[0]=i("h1",null,"Seeding Themes",-1)),a(s),e[1]||(e[1]=l(`<p>Themes support the ability to import sample content from seed scripts, including database content and <a href="./../../cms/tailor/introduction.html">Tailor blueprints</a>. A specific folder inside the theme called <strong>seeds</strong> is used along with a directory structure to provide the content.</p><h2 id="directory-structure"><a href="#directory-structure" class="header-anchor">#</a> Directory Structure</h2><p>Below you can see an example seed directory structure. The <strong>blueprints</strong> directory contains any blueprint templates used by the theme, these are imported automatically to the <strong>app/blueprints</strong> directory with a nested directory called <strong>mywebsite</strong>. The <strong>data.yaml</strong> file contains instructions on how to import the content in to the database.</p><pre class="dir-container"><code><p>├── themes
|   └── mywebsite
|       └── <code>seeds</code>  <em>← Theme Seed Directory</em>
|           ├── blueprints
|           |   └── post.yaml  <em>← Blueprint File</em>
|           ├── lang
|           |   └── en.json  <em>← Language File</em>
|           ├── data
|           |   └── blog-posts.json  <em>← Data File</em>
|           └── data.yaml  <em>← Seeding Script</em></p>
</code></pre><h2 id="importing-blueprints"><a href="#importing-blueprints" class="header-anchor">#</a> Importing Blueprints</h2><div class="custom-block aside"><p>Since blueprints do not depend on any specific file or directory structure, they can be moved around freely.</p></div><p>When importing blueprints, simply place the blueprint files in the <strong>blueprints</strong> directory. It does not use any configuration, when seeding all blueprints are simply copied to the <strong>app/blueprints</strong> directory. A new directory is created inside that has the same name as the theme. The blueprints are placed inside this new directory.</p><h2 id="importing-languages"><a href="#importing-languages" class="header-anchor">#</a> Importing Languages</h2><p>As an optional feature, languages can be imported to the <strong>app/lang</strong> directory by placing the <a href="./../../extend/system/localization.html">JSON language files</a> in the <strong>lang</strong> directory. This makes it possible to translate labels and other descriptions inside blueprints. If a language file already exists in the application language directory, then the language strings will be merged together.</p><h2 id="importing-data"><a href="#importing-data" class="header-anchor">#</a> Importing Data</h2><p>The <strong>data.yaml</strong> file contains a specific format used for importing content in to the database. In the example below, two sets of data are imported to the database for Tailor entry content.</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token punctuation">-</span>
    <span class="token key atrule">name</span><span class="token punctuation">:</span> Blog Post Data
    <span class="token key atrule">class</span><span class="token punctuation">:</span> Tailor\\Models\\RecordImport
    <span class="token key atrule">file</span><span class="token punctuation">:</span> seeds/data/blog<span class="token punctuation">-</span>posts.json
    <span class="token key atrule">attributes</span><span class="token punctuation">:</span>
        <span class="token key atrule">file_format</span><span class="token punctuation">:</span> json
        <span class="token key atrule">blueprint_uuid</span><span class="token punctuation">:</span> edcd102e<span class="token punctuation">-</span>0525<span class="token punctuation">-</span>4e4d<span class="token punctuation">-</span>b07e<span class="token punctuation">-</span>633ae6c18db6
<span class="token punctuation">-</span>
    <span class="token key atrule">name</span><span class="token punctuation">:</span> Blog Category Data
    <span class="token key atrule">class</span><span class="token punctuation">:</span> Tailor\\Models\\RecordImport
    <span class="token key atrule">file</span><span class="token punctuation">:</span> seeds/data/blog<span class="token punctuation">-</span>categories.json
    <span class="token key atrule">attributes</span><span class="token punctuation">:</span>
        <span class="token key atrule">file_format</span><span class="token punctuation">:</span> json
        <span class="token key atrule">blueprint_uuid</span><span class="token punctuation">:</span> b022a74b<span class="token punctuation">-</span>15e6<span class="token punctuation">-</span>4c6b<span class="token punctuation">-</span>9eb9<span class="token punctuation">-</span>17efc5103543
</code></pre></div><p>The YAML file should define an array where each item in the array supports the following properties.</p><div class="table"><table tabindex="0"><thead><tr><th>Property</th><th>Description</th></tr></thead><tbody><tr><td><strong>name</strong></td><td>gives the import step a name to display to the user.</td></tr><tr><td><strong>class</strong></td><td>refers to a model that extends the interface of <code>Backend\\Models\\ImportModel</code>.</td></tr><tr><td><strong>file</strong></td><td>refers to the JSON data file that contains the content to import.</td></tr><tr><td><strong>attributes</strong></td><td>a list of attributes to set on the Import Model before importing.</td></tr></tbody></table></div><h3 id="example-data-file"><a href="#example-data-file" class="header-anchor">#</a> Example Data File</h3><p>The following is an example of a JSON file that can be used to import blog categories. Each item in the JSON array produces an imported record in the database with the supplied attributes. Providing an <strong>id</strong> attribute allows records to link across multiple imports.</p><div class="language-json extra-class"><pre class="language-json"><code><span class="token punctuation">[</span>
    <span class="token punctuation">{</span>
        <span class="token property">&quot;id&quot;</span><span class="token operator">:</span> <span class="token number">1</span><span class="token punctuation">,</span>
        <span class="token property">&quot;title&quot;</span><span class="token operator">:</span> <span class="token string">&quot;Announcements&quot;</span><span class="token punctuation">,</span>
        <span class="token property">&quot;slug&quot;</span><span class="token operator">:</span> <span class="token string">&quot;announcements&quot;</span>
    <span class="token punctuation">}</span><span class="token punctuation">,</span>
    <span class="token punctuation">{</span>
        <span class="token property">&quot;id&quot;</span><span class="token operator">:</span> <span class="token number">2</span><span class="token punctuation">,</span>
        <span class="token property">&quot;title&quot;</span><span class="token operator">:</span> <span class="token string">&quot;News&quot;</span><span class="token punctuation">,</span>
        <span class="token property">&quot;slug&quot;</span><span class="token operator">:</span> <span class="token string">&quot;news&quot;</span>
    <span class="token punctuation">}</span>
<span class="token punctuation">]</span>
</code></pre></div><h2 id="seeding-a-theme"><a href="#seeding-a-theme" class="header-anchor">#</a> Seeding a Theme</h2><p>The <code>theme:seed</code> artisan command is used to seed a theme.</p><div class="language-bash extra-class"><pre class="language-bash"><code>php artisan theme:seed <span class="token operator">&lt;</span>theme name<span class="token operator">&gt;</span>
</code></pre></div><p>You may also use the <code>--root</code> option to instruct the command to import the blueprints in to the root directory instead of in a nested directory.</p><div class="language-bash extra-class"><pre class="language-bash"><code>php artisan theme:seed <span class="token operator">&lt;</span>theme name<span class="token operator">&gt;</span> <span class="token parameter variable">--root</span>
</code></pre></div><div class="custom-block tip"><p>You may also seed a theme using the admin panel by navigating to <strong>Settings → Frontend Theme → Manage → Seed Content</strong>.</p></div>`,23))])}const f=o(c,[["render",d]]);export{y as __pageData,f as default};
